def match_parens(lst):
    # Step 1: Check if the input list contains only '(' and ')' characters
    if any(char not in ['(', ')'] for string in lst for char in string):
        return 'No'

    # Step 2: Concatenate the strings in the list to form a single string
    concatenated_string = ''.join(lst)

    # Step 3: Use a stack to check if the concatenated string has balanced parentheses
    stack = []
    for char in concatenated_string:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                return 'No'
            stack.pop()

    # Step 4: Return 'Yes' if balanced, 'No' if not
